models.css:
.card {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  text-align: center;
  color: #263238;
  background-color: #f0f4f8;
  padding: 14px;
}
.card-box {
  max-width: 580px;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 18px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  padding: 22px 20px;
  box-sizing: border-box;
}
.badge {
  display: inline-block;
  background: #1976D2;
  color: #ffffff;
  font-size: 13.5px;
  font-weight: bold;
  padding: 5px 16px;
  border-radius: 20px;
  margin-bottom: 12px;
}
.audio-panel {
  margin: 12px 0;
  padding: 16px 12px;
  background: #e8f4fd;
  border-radius: 14px;
  border: 1px solid #d0e7fb;
}
.audio-tip {
  font-size: 13px;
  color: #455a64;
  margin-top: 8px;
  font-weight: 500;
}
.front-grid-preview {
  margin: 16px auto 6px;
  padding: 14px 16px;
  border: 2px dashed #90caf9;
  border-radius: 14px;
  background: #fbfdff;
}
.blank-four-lines {
  width: 220px;
  margin: 0 auto 10px;
  border-left: 2px solid #90caf9;
  border-right: 2px solid #90caf9;
}
.blank-four-lines .space {
  height: 20px;
  background: #f8fbff;
}
.blank-four-lines .space.mid {
  background: #fff9e6;
}
.blank-four-lines .line-top {
  border-top: 2px solid #ef5350;
}
.blank-four-lines .line-mid {
  border-top: 1.5px dashed #42a5f5;
}
.blank-four-lines .line-base {
  border-top: 2.5px solid #d32f2f;
}
.blank-four-lines .line-bot {
  border-bottom: 2px solid #42a5f5;
}
.write-guide {
  font-size: 13.5px;
  color: #455a64;
  line-height: 1.6;
}
/* 背面隐藏正面的空白练习框，直接聚焦四线三格答案 */
#answer ~ .back-wrap ~ style,
.back-mode .front-only {
  display: none;
}
.answer-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin: 6px 0 14px;
}
.print-pair {
  font-family: "Comic Sans MS", "Century Gothic", "Segoe UI", Arial, sans-serif;
  font-size: 46px;
  font-weight: bold;
  padding: 2px 18px;
  border-radius: 12px;
  background: #f5f7fa;
  border: 2px solid #e0e6ed;
}
.ipa-tag {
  font-size: 24px;
  color: #e65100;
  font-weight: bold;
  background: #fff3e0;
  padding: 4px 14px;
  border-radius: 10px;
}
.grid-img-box {
  margin: 12px 0;
  background: #ffffff;
  border-radius: 14px;
  overflow: hidden;
}
.grid-img-box img {
  width: 100%;
  max-width: 540px;
  height: auto;
  display: block;
  margin: 0 auto;
}
.detail-box {
  text-align: left;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 12px 16px;
  margin-top: 12px;
  font-size: 13.5px;
  line-height: 1.75;
}
.detail-item {
  margin-bottom: 5px;
}
.detail-item:last-child {
  margin-bottom: 0;
}
.detail-label {
  font-weight: bold;
  color: #1e293b;
}
